import { useEffect, useMemo, useRef, useState } from 'react'
import { useGraph } from '@react-three/fiber'
import { useGLTF, useProgress } from '@react-three/drei'
import { SkeletonUtils } from 'three-stdlib'
import gsap from "gsap";
const contactBoyPath = import.meta.env.BASE_URL +"/models/boy-transformed.glb";

export function HeroBoy(props) {
    const group = useRef();
    const { progress, total } = useProgress();
    const [isIntroAnimationDone, setIsIntroAnimationDone] = useState(false);

    const { scene } = useGLTF(contactBoyPath);
    const clone = useMemo(() => SkeletonUtils.clone(scene), [scene]);
    const { nodes, materials } = useGraph(clone);

    useEffect(() => {
        if (total > 0 && progress === 100 && group.current && !isIntroAnimationDone) {
            gsap.from(group.current.rotation, {
                y: Math.PI,
                duration: 1.5,
                ease: "power1.inOut",
                onComplete: () => setIsIntroAnimationDone(true),
            });
        }
    }, [progress, total, isIntroAnimationDone]);

    useEffect(() => {
        if (isIntroAnimationDone && group.current) {
            const handleScroll = () => {
                const scrollY = window.scrollY;
                const windowHeight = window.innerHeight;

                const heroEnd = windowHeight * 0.8; // Start transition before hero ends
                const transitionDistance = windowHeight *1; // How long the transition takes

                let scrollProgress = 0;

                if (scrollY >= heroEnd && scrollY <= heroEnd + transitionDistance) {
                    scrollProgress = (scrollY - heroEnd) / transitionDistance;
                } else if (scrollY > heroEnd + transitionDistance) {
                    scrollProgress = 1;
                }

                scrollProgress = Math.max(0, Math.min(1, scrollProgress));

                if (group.current) {
                    const startX = 0;
                    const endX = 12;
                    const startY = -2;
                    const endY = -2;
                    const startZ = 0;
                    const endZ = 0;
                    const targetX = startX + (endX - startX) * scrollProgress;
                    const targetY = startY + (endY - startY) * scrollProgress;
                    const targetZ = startZ + (endZ - startZ) * scrollProgress;

                    gsap.to(group.current.position, {
                        x: targetX,
                        y: targetY,
                        z: targetZ,
                        duration: 0.6,
                        ease: "power2.out",
                    });
                    const startRotationY = 0;
                    const endRotationY = Math.PI * 5;
                    const targetRotationY = startRotationY + (endRotationY - startRotationY) * scrollProgress;

                    gsap.to(group.current.rotation, {
                        x: 0,
                        y: targetRotationY,
                        z: 0,
                        duration: 0.6,
                        ease: "power2.out",
                    });
                    const startScale =3;
                    const endScale = 2.5;
                    const targetScale = startScale + (endScale - startScale) * scrollProgress;

                    gsap.to(group.current.scale, {
                        x: targetScale,
                        y: targetScale,
                        z: targetScale,
                        duration: 0.6,
                        ease: "power2.out",
                    });

                    if (group.current.traverse) {
                        const targetOpacity = 1 - scrollProgress;
                        group.current.traverse((child) => {
                            if (child.material) {
                                if (!child.material.transparent) {
                                    child.material.transparent = true;
                                }
                                gsap.to(child.material, {
                                    opacity: Math.max(targetOpacity, 0),
                                    duration: 0.6,
                                    ease: "power2.out",
                                });
                            }
                        });
                    }

                }
            };

            let ticking = false;
            const throttledScroll = () => {
                if (!ticking) {
                    requestAnimationFrame(() => {
                        handleScroll();
                        ticking = false;
                    });
                    ticking = true;
                }
            };

            window.addEventListener("scroll", throttledScroll, { passive: true });

            handleScroll();

            return () => window.removeEventListener("scroll", throttledScroll);
        }
    }, [isIntroAnimationDone]);

    return (
        <group
            ref={group}
            {...props}
            dispose={null}
            position={[0, -2, 0]}  // Initial position in 3D space
            scale={[1.8, 1.8, 1.8]} // Initial scale
        >
            <primitive object={nodes.Hips} />
            <skinnedMesh geometry={nodes.Wolf3D_Hair.geometry} material={materials.Wolf3D_Hair} skeleton={nodes.Wolf3D_Hair.skeleton} />
            <skinnedMesh geometry={nodes.Wolf3D_Outfit_Top.geometry} material={materials.Wolf3D_Outfit_Top} skeleton={nodes.Wolf3D_Outfit_Top.skeleton} />
            <skinnedMesh geometry={nodes.Wolf3D_Outfit_Bottom.geometry} material={materials.Wolf3D_Outfit_Bottom} skeleton={nodes.Wolf3D_Outfit_Bottom.skeleton} />
            <skinnedMesh geometry={nodes.Wolf3D_Outfit_Footwear.geometry} material={materials.Wolf3D_Outfit_Footwear} skeleton={nodes.Wolf3D_Outfit_Footwear.skeleton} />
            <skinnedMesh geometry={nodes.Wolf3D_Body.geometry} material={materials.Wolf3D_Body} skeleton={nodes.Wolf3D_Body.skeleton} />
            <skinnedMesh name="EyeLeft" geometry={nodes.EyeLeft.geometry} material={materials.Wolf3D_Eye} skeleton={nodes.EyeLeft.skeleton} morphTargetDictionary={nodes.EyeLeft.morphTargetDictionary} morphTargetInfluences={nodes.EyeLeft.morphTargetInfluences} />
            <skinnedMesh name="EyeRight" geometry={nodes.EyeRight.geometry} material={materials.Wolf3D_Eye} skeleton={nodes.EyeRight.skeleton} morphTargetDictionary={nodes.EyeRight.morphTargetDictionary} morphTargetInfluences={nodes.EyeRight.morphTargetInfluences} />
            <skinnedMesh name="Wolf3D_Head" geometry={nodes.Wolf3D_Head.geometry} material={materials.Wolf3D_Skin} skeleton={nodes.Wolf3D_Head.skeleton} morphTargetDictionary={nodes.Wolf3D_Head.morphTargetDictionary} morphTargetInfluences={nodes.Wolf3D_Head.morphTargetInfluences} />
            <skinnedMesh name="Wolf3D_Teeth" geometry={nodes.Wolf3D_Teeth.geometry} material={materials.Wolf3D_Teeth} skeleton={nodes.Wolf3D_Teeth.skeleton} morphTargetDictionary={nodes.Wolf3D_Teeth.morphTargetDictionary} morphTargetInfluences={nodes.Wolf3D_Teeth.morphTargetInfluences} />

        </group>
    )
}

useGLTF.preload(contactBoyPath)